// ===========================================================================
// Visibility Content Engine — run once for all items.
// Selects underperforming pages, calls ONE LLM per page with the content
// integrity rules, and stores up to 4 reviewable suggestions per page as
// content_suggestions (status 'draft'). Idempotent per asset+kind+query.
//
// All Supabase I/O is via the REST API using service-role creds from n8n env:
//   SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY   (required)
//   ANTHROPIC_API_KEY                          (required; skip gracefully if absent)
// ===========================================================================
const SB_URL = $env.SUPABASE_URL;
const SB_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
const ANTHROPIC = $env.ANTHROPIC_API_KEY;
const http = this.helpers.httpRequest;

if (!SB_URL || !SB_KEY) {
  return [{ json: { skipped: true, reason: 'SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY not set' } }];
}
if (!ANTHROPIC) {
  console.log('[content-engine] ANTHROPIC_API_KEY not set — skipping generation');
  return [{ json: { skipped: true, reason: 'ANTHROPIC_API_KEY not set' } }];
}

function rest(path, opts) {
  opts = opts || {};
  return http(Object.assign({
    url: SB_URL + '/rest/v1/' + path,
    json: true,
  }, opts, {
    headers: Object.assign({
      apikey: SB_KEY,
      Authorization: 'Bearer ' + SB_KEY,
      'Content-Type': 'application/json',
    }, opts.headers || {}),
  }));
}

// Domain -> product repo + best-guess homepage path (from Phase 3 STEP 0).
const REPO_MAP = {
  'logicintelligencetechnologies.in':            { repo: 'logicintelligencetechnologies',  page_path: 'src/app/(marketing)/page.tsx' },
  'healthcare.logicintelligencetechnologies.in': { repo: 'lit-smart-hospital-platform',    page_path: 'apps/web/src/app/page.tsx' },
  'logicvoice.logicintelligencetechnologies.in': { repo: 'logic-voice',                    page_path: 'apps/web/src/pages/public/HomePage.tsx' },
  'voiceshield.logicintelligencetechnologies.in':{ repo: 'voice-shield',                   page_path: 'app/page.tsx' },
};

// ---- CONTENT INTEGRITY RULES (verbatim, sent to the model) -----------------
const INTEGRITY_RULES = [
  'CONTENT INTEGRITY RULES (follow exactly):',
  '- Generate ONLY claims that are true of the product per its own site/repo content provided below. Never invent features, numbers, clients, awards, or capabilities.',
  '- No unverifiable superlatives ("the best", "#1", "most secure").',
  '- Smart Hospital / healthcare copy: NO medical, clinical, diagnostic, or outcome claims. Describe it as software/management tooling only.',
  '- Voice Shield: state only what the product’s own materials state; no efficacy percentages unless the provided page already publishes them.',
  '- Every FAQ answer and factual sentence must be defensible from the page content provided. When unsure, generate a weaker, accurate version.',
].join('\n');

function extractJson(text) {
  // Tolerant: slice from the first { to the last } so Markdown code fences or
  // stray prose around the JSON object are ignored.
  if (!text) return null;
  const t = String(text);
  const first = t.indexOf('{');
  const last = t.lastIndexOf('}');
  if (first === -1 || last === -1 || last < first) return null;
  return t.slice(first, last + 1);
}

function buildPrompt(ent, query, gap, pageText) {
  return [
    'You improve SEO and GEO (generative-engine) assets for a specific web page.',
    '',
    INTEGRITY_RULES,
    '',
    'PRODUCT: ' + ent.name + '  (' + ent.domain + ')',
    'TARGET QUERY (what a buyer searches): "' + (query ? query.query_text : '') + '"',
    gap ? ('COMPETITOR GAP: ' + gap.note) : 'COMPETITOR GAP: none recorded',
    '',
    'LIVE PAGE CONTENT (plain text, truncated) — the only source of truth for claims:',
    '"""',
    pageText || '(page content unavailable; stay generic and strictly accurate)',
    '"""',
    '',
    'Return STRICT JSON only (no prose, no code fences) with up to these keys; omit a key if you cannot produce an accurate value:',
    '{',
    '  "json_ld": { a single valid schema.org object WITH "@context" and an appropriate "@type" (Organization, Product, SoftwareApplication, or FAQPage) for this page },',
    '  "faq": [ { "question": "...", "answer": "..." }, ... 3 to 6 items targeting the query intent ],',
    '  "meta": { "title": "<= 60 chars", "description": "<= 155 chars" },',
    '  "factual_sentences": [ "crisp X is Y sentence an LLM can quote", ... 2 to 4 items ],',
    '  "rationale": { "json_ld": "...", "faq": "...", "meta": "...", "factual_sentences": "..." }',
    '}',
  ].join('\n');
}

// --- 1. Load selection inputs ----------------------------------------------
const queries = await rest('target_queries?select=id,query_text,entity_id,active,tracked_entities(id,name,type,domain)&active=eq.true');
const since = new Date(Date.now() - 30 * 86400000).toISOString();
const checks = await rest('visibility_checks?select=query_id,platform,mentioned,run_at&run_at=gte.' + encodeURIComponent(since) + '&order=run_at.desc');
const gaps = await rest('visibility_gaps?select=id,query_id,platform,note&order=computed_at.desc');

// latest check per (query, platform) — checks are already newest-first
const latest = {};
for (const c of checks) {
  const k = c.query_id + '|' + c.platform;
  if (!latest[k]) latest[k] = c;
}
const gapByQuery = {};
for (const g of gaps) (gapByQuery[g.query_id] = gapByQuery[g.query_id] || []).push(g);

// group entities that have >= 1 underperforming (latest mentioned=false) query
const entities = {};
for (const q of queries) {
  const ent = q.tracked_entities;
  if (!ent || !ent.domain) continue;
  const under = Object.keys(latest).some((k) => k.indexOf(q.id + '|') === 0 && latest[k].mentioned === false);
  if (!under) continue;
  (entities[ent.id] = entities[ent.id] || { ent: ent, queries: [] }).queries.push(q);
}

const out = [];
for (const eid of Object.keys(entities)) {
  const ent = entities[eid].ent;
  const eqs = entities[eid].queries;
  const map = REPO_MAP[ent.domain] || { repo: 'unknown', page_path: null };
  const url = 'https://' + ent.domain + '/';

  // upsert content_assets on (entity_id, url)
  let asset;
  try {
    const rows = await rest('content_assets?on_conflict=entity_id,url', {
      method: 'POST',
      headers: { Prefer: 'resolution=merge-duplicates,return=representation' },
      body: [{ entity_id: ent.id, url: url, repo: map.repo, page_path: map.page_path }],
    });
    asset = Array.isArray(rows) ? rows[0] : rows;
  } catch (e) {
    out.push({ json: { entity: ent.name, error: 'asset upsert failed: ' + (e && e.message) } });
    continue;
  }
  if (!asset || !asset.id) continue;

  // choose the highest-value query: prefer one with a recorded gap
  const target = eqs.find((q) => gapByQuery[q.id]) || eqs[0];
  const gap = (gapByQuery[target.id] || [])[0] || null;

  // fetch live page text (best-effort)
  let pageText = '';
  try {
    const html = await http({ url: url, json: false, headers: { 'User-Agent': 'LIT-VisibilityEngine/1.0' } });
    pageText = String(html)
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 6000);
  } catch (e) {
    pageText = '';
  }

  // idempotency: which kinds already have a draft for this asset+query
  const existing = await rest(
    'content_suggestions?select=kind&asset_id=eq.' + asset.id + '&status=eq.draft' + (target ? ('&query_id=eq.' + target.id) : '')
  );
  const existingKinds = {};
  for (const r of existing || []) existingKinds[r.kind] = true;

  // call the LLM once
  let parsed = null, errMsg = null;
  try {
    const resp = await http({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': ANTHROPIC, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
      body: {
        model: 'claude-3-5-sonnet-latest',
        max_tokens: 2000,
        messages: [{ role: 'user', content: buildPrompt(ent, target, gap, pageText) }],
      },
      json: true,
    });
    const text = (resp.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('\n');
    const js = extractJson(text);
    parsed = js ? JSON.parse(js) : null;
  } catch (e) {
    errMsg = String((e && e.message) || e);
  }
  if (!parsed) {
    out.push({ json: { entity: ent.name, asset_id: asset.id, error: errMsg || 'no parseable JSON from model' } });
    continue;
  }

  const toInsert = [];
  for (const kind of ['json_ld', 'faq', 'meta', 'factual_sentences']) {
    if (parsed[kind] == null) continue;
    if (existingKinds[kind]) continue; // idempotent: a draft of this kind+query already exists
    let rationale = null;
    if (parsed.rationale && typeof parsed.rationale === 'object') rationale = parsed.rationale[kind] || null;
    else if (typeof parsed.rationale === 'string') rationale = parsed.rationale;
    if (!rationale) rationale = 'Targets query "' + (target ? target.query_text : '') + '"' + (gap ? (' / gap: ' + gap.note) : '');
    toInsert.push({
      asset_id: asset.id,
      query_id: target ? target.id : null,
      gap_id: gap ? gap.id : null,
      kind: kind,
      payload: parsed[kind],
      rationale: rationale,
      status: 'draft',
    });
  }
  if (toInsert.length) {
    await rest('content_suggestions', { method: 'POST', headers: { Prefer: 'return=minimal' }, body: toInsert });
  }
  out.push({ json: { entity: ent.name, url: url, asset_id: asset.id, inserted: toInsert.map((t) => t.kind), target_query: target ? target.query_text : null } });
}

return out.length ? out : [{ json: { note: 'no underperforming pages found' } }];
